window.RP_SESSION={"id":"S-9cd004f7c7e6","messages":[{"id":"RP-0175135","time":"2026-06-17T19:27:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"오늘도 평화로운 어용 어용 어용 대장간","characters":["P-55e987e3c831"]},{"id":"RP-0175136","time":"2026-06-17T19:27:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"일거리는 항상 만들면 생기는 것인데요.","characters":["P-55e987e3c831"]},{"id":"RP-0175137","time":"2026-06-17T19:28:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"오늘은 작업장에서 나무절구와 석회석 덩어리들을 담은 가죽부대를 들고 나옵니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175138","time":"2026-06-17T19:28:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"강가의 넓직한 돌 위에 석회석을 담은 가죽부대를 올려놓고","characters":["P-55e987e3c831"]},{"id":"RP-0175139","time":"2026-06-17T19:29:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그대로 뭉특한 나무망치로 줘팸해줍니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175140","time":"2026-06-17T19:29:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"힘...은 아닐겁니다. 석회석은 무르니까요.","characters":["P-55e987e3c831"]},{"id":"RP-0175141","time":"2026-06-17T19:29:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"!체력","characters":["P-55e987e3c831"]},{"id":"RP-0175142","time":"2026-06-17T19:29:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'브랜'의 체력 판정 :\n[4] + [1] = [5]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0175143","time":"2026-06-17T19:30:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"지치면 쉬었다 해 임마","characters":["P-55e987e3c831"]},{"id":"RP-0175144","time":"2026-06-17T19:30:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"나무 망치로 석회석들을 작은 조각들로 쪼개는데, 대충 하다가 강에 발 담그고 쉽니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175145","time":"2026-06-17T19:30:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"워터스킨에 담은 우물물도 마시고요.","characters":["P-55e987e3c831"]},{"id":"RP-0175146","time":"2026-06-17T19:34:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"달그락\n   달그락...\n\n\n이게 무슨 소리 일까요?","characters":[]},{"id":"RP-0175147","time":"2026-06-17T19:35:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"머.. 먼소리요?","characters":["P-55e987e3c831"]},{"id":"RP-0175148","time":"2026-06-17T19:35:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"달그락 달그락...","characters":[]},{"id":"RP-0175149","time":"2026-06-17T19:35:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"브랜 근처에서 나는 소리면 주변을 둘러봅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175150","time":"2026-06-17T19:37:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"달그락 달그락...\n\n어디에서 나고 있나요?\n\n소리를 쫒아가보세요.","characters":[]},{"id":"RP-0175151","time":"2026-06-17T19:38:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"뭐야...\" 강물에 담그고 있던 발을 털고, 바지에 대충 서로 문질러 닦은 다음 신발까지 다시 신습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175152","time":"2026-06-17T19:38:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그리고 소리를 쫓아가요. 달그락 거리는 소리가 멀리 울려 퍼질 일도 없고, 근처일 겁니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175153","time":"2026-06-17T19:43:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"그렇습니다. 이 근처인 것 같습니다.\n\n달그락 달그락...\n\n무슨 소리일까요?\n\n주변을 둘러보세요. 그리고 상상해보세요. 뭐가 보이나요?","characters":[]},{"id":"RP-0175154","time":"2026-06-17T19:44:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"어설픈 용맹 오픈톡방 창이요...","characters":["P-55e987e3c831"]},{"id":"RP-0175155","time":"2026-06-17T19:44:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"거기에 티아맷 님이 달그락 달그락 해골이다 라고 하는 것 까지 보입니다...","characters":["P-55e987e3c831"]},{"id":"RP-0175156","time":"2026-06-17T19:44:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"근데 전 누가 설거지 하는 소리 같거든여!!!!!","characters":["P-55e987e3c831"]},{"id":"RP-0175157","time":"2026-06-17T19:46:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"오, 사실일지도 몰라요.\n\n지능 판정 해볼까요?","characters":[]},{"id":"RP-0175158","time":"2026-06-17T19:46:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"지능 최악","characters":["P-55e987e3c831"]},{"id":"RP-0175159","time":"2026-06-17T19:46:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-55e987e3c831"]},{"id":"RP-0175160","time":"2026-06-17T19:46:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'브랜'의 지능 판정 :\n[2] + [-1] = [1]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-0175161","time":"2026-06-17T19:46:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"따흐악","characters":["P-55e987e3c831"]},{"id":"RP-0175162","time":"2026-06-17T19:47:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"뭣.","characters":[]},{"id":"RP-0175163","time":"2026-06-17T19:48:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"달그락\n 달그락\n 달그락\n달그락\n   달그락    달그락\n      달그락 \n  달그락   달그락\n      달그락\n   달그락...\n\n소, 소리가 더 거세게 들려옵니다...!\n\n분명 이 근방인 것 같아요. 어쩌면 더 가까이일지두요...!","characters":[]},{"id":"RP-0175164","time":"2026-06-17T19:48:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"영 감이 안 잡힙니다. 시야에 보인다면 진작 보여야 했을 것인데.","characters":["P-55e987e3c831"]},{"id":"RP-0175165","time":"2026-06-17T19:48:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"뭔데 진짜?!\"","characters":["P-55e987e3c831"]},{"id":"RP-0175166","time":"2026-06-17T19:49:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"황급히 강에서 물러나며 근처에 있던 나무 몽댕이라도 집어들어요. 절구랑 세트!","characters":["P-55e987e3c831"]},{"id":"RP-0175167","time":"2026-06-17T19:49:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"'달그락' 거리는 소리는 어떨때 날까요?","characters":[]},{"id":"RP-0175168","time":"2026-06-17T19:50:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"막 몸에 이것저것 달고 걸어다닐 때처럼 서로 물건들이 부딪히면서 나요","characters":["P-55e987e3c831"]},{"id":"RP-0175169","time":"2026-06-17T19:50:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"아니면 누군가 입으로 달그락이라고 중얼거린다면 그런 소리가 나죠.","characters":["P-55e987e3c831"]},{"id":"RP-0175170","time":"2026-06-17T19:50:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"끊임없이.","characters":["P-55e987e3c831"]},{"id":"RP-0175171","time":"2026-06-17T19:51:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"아니면 차량에서 어퍼 암 부싱이 닳거나 하면 달그락 거리는 소리가 날 수 있는데 차는 안 보이는군여.","characters":["P-55e987e3c831"]},{"id":"RP-0175172","time":"2026-06-17T19:53:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"맞아요...!\n\n누군가 입으로 '달그락' 이란 단어를 소리내어 얘기했거나,\n\n사물이 부딪힐 때 나는 소리죠.\n\n조금 더 면밀히 생각해볼까요?\n\n쇠가 부딪힐때 나는 소리와, 도기가 부딪히는 소리가 또 다르고...\n\n나무 그릇이 물 속에서 출렁이며 부딪히는 소리일지도 모르구요.\n\n상상력을 확장시키고, 다시 한 번 주변을 둘러보세요. 달그락거리는 소리가 날 만한 무언가가 브랜 주변에 있을까요?","characters":[]},{"id":"RP-0175173","time":"2026-06-17T19:53:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"소리가 나니까 분명 있습니다. 시야를 낮춥니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175174","time":"2026-06-17T19:55:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"좋아요.\n\n바닥은 흙인가요? 자갈인가요? 아니면 풀밭인가요?","characters":[]},{"id":"RP-0175175","time":"2026-06-17T19:56:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"아직 강 주변인데, 세가지 다 가능성이 있그등여. 자갈이라 하겠습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175176","time":"2026-06-17T19:59:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"좋습니다. 저도 보이네요! \n\n물과 가까운 땅이라 풀포기가 적고, 흙은 강물에 약간 씻겨져 낮은 토사와 대부분의 자갈로 이루어진 강변이에요. 군데군데 수생식물들이 솟아있는 것도 보입니다.\n\n이제 레이어를 쌓아봅시다.\n\n우리는 '달그락거리는 소리가 나는 이유'를 마일스톤으로 두어야해요.\n\n자갈 밭 위, 무엇이 보입니까?","characters":[]},{"id":"RP-0175177","time":"2026-06-17T20:00:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"https://youtu.be/GAmtwLOhe6Q?si=y6r9bbineTyIJ80A","characters":[]},{"id":"RP-0175178","time":"2026-06-17T20:01:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"곧 와이프가 와요! 어서요 브랜!","characters":[]},{"id":"RP-0175179","time":"2026-06-17T20:01:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"잠깐. 이거 보인다는 게 브랜 입장에서 보면 진작 보였어야 할 무언가인데, 제가 정하라는 말이였나요??? 혹시?????","characters":["P-55e987e3c831"]},{"id":"RP-0175180","time":"2026-06-17T20:02:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"너무 확대를 하다간 보여야 할 것도 보이지 않을 겁니다. 바로 앞의 사람 얼굴을 현미경으로 들여다 보는 꼴이겠죠.","characters":["P-55e987e3c831"]},{"id":"RP-0175181","time":"2026-06-17T20:03:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"무난하게 누군가 설거지 따위를 하고 있었다고 생각해보겠습니다. 아니면 브랜보다 낮은 키의 누군가가 수레를 끌고 가거나요. 어느쪽이든 브랜이 망치질 하느라 못 들었을 거 같네요.","characters":["P-55e987e3c831"]},{"id":"RP-0175182","time":"2026-06-17T20:03:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"제발 이 진동이 끝난 후에 어스웜같은 게 바닥에서 뛰쳐나오는 거 빼고 무난한 거 다 좋슴다","characters":["P-55e987e3c831"]},{"id":"RP-0175183","time":"2026-06-17T20:04:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"좋습니다...! 설거지에 걸어볼까요!?\n\n브랜, 지능!","characters":[]},{"id":"RP-0175184","time":"2026-06-17T20:05:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"아까랑 같은 꼴이 나는 거 아임까","characters":["P-55e987e3c831"]},{"id":"RP-0175185","time":"2026-06-17T20:05:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-55e987e3c831"]},{"id":"RP-0175186","time":"2026-06-17T20:05:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'브랜'의 지능 판정 :\n[9] + [-1] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0175187","time":"2026-06-17T20:05:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"ㅋㅋㅋㅋ","characters":[]},{"id":"RP-0175188","time":"2026-06-17T20:05:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"오!","characters":[]},{"id":"RP-0175189","time":"2026-06-17T20:05:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"오케이 오케이","characters":["P-55e987e3c831"]},{"id":"RP-0175190","time":"2026-06-17T20:05:00+09:00","room":"RP","name":"진행 / 강가의 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"정확합니다. 그 소리는... 강 건너편에서 누군가 설거지를 하고있는 소리입니다.","characters":[]},{"id":"RP-0175191","time":"2026-06-17T20:05:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"아... 피곤한가.\" 마른 세수를 합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175192","time":"2026-06-17T20:06:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"손이나 흔들어 주죠. \"안녕하세요!\"","characters":["P-55e987e3c831"]},{"id":"RP-0175193","time":"2026-06-17T20:28:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"이내 이어서 작업을 시작합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175194","time":"2026-06-17T20:28:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"가죽부대의 내용물을 절구 안에 쏟죠. 작은 석회석 조각들이 쏟아집니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175195","time":"2026-06-17T20:29:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그걸 나무 공이로 더 잘게 빻아요.","characters":["P-55e987e3c831"]},{"id":"RP-0175196","time":"2026-06-17T20:35:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그렇게 곱게 빻은 석회가루를 다시 가죽부대에 담습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175197","time":"2026-06-17T20:35:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"나무 절구에 거꾸로 씌워서, 절구를 휙 뒤집는 식으로.","characters":["P-55e987e3c831"]},{"id":"RP-0175198","time":"2026-06-17T20:36:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그렇게 빻은 석회가루를 대장간 창고에 집어넣고, 솥과 장작을 챙겨 강변으로 들고 나옵니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175199","time":"2026-06-17T20:36:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"전에 통나무에서 벗겨둔 나무껍질도 마대자루 통째로요.","characters":["P-55e987e3c831"]},{"id":"RP-0175200","time":"2026-06-17T20:37:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"강변에 돌로 화덕처럼 틀을 만들고, 그 위에 솥을 얹어요.","characters":["P-55e987e3c831"]},{"id":"RP-0175201","time":"2026-06-17T20:37:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그 아래에 장작을 좀 넣고 파이어 스타터를 튀겨 불을 붙이죠.","characters":["P-55e987e3c831"]},{"id":"RP-0175202","time":"2026-06-17T20:37:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"강에서 물을 길어 솥을 채우고, 나무껍질을 푹 삶습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175203","time":"2026-06-17T20:38:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"진한 차를 우리듯 나무 껍질 물을 우려내고","characters":["P-55e987e3c831"]},{"id":"RP-0175204","time":"2026-06-17T20:39:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그제 만들어둔 나무통을 대장간 창고에서 꺼내옵니다. 데굴데굴 대각선으로 굴려요.","characters":["P-55e987e3c831"]},{"id":"RP-0175205","time":"2026-06-17T20:39:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-55e987e3c831"]},{"id":"RP-0175206","time":"2026-06-17T20:40:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"통을 솥 근처에 두고, 솥이 식을 때까지 기다리기로 합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175207","time":"2026-06-17T20:40:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-55e987e3c831"]},{"id":"RP-0175208","time":"2026-06-17T20:40:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
